import static org.junit.jupiter.api.Assertions.*;
class NativePdfPrefixedScopeTest {
    private static final String SHA="a".repeat(64),FRAME="normalized_rendered_crop_top_left";
    @Test void exactPrefixedRootKeepsNativeChildrenAndEndPeer() {
        for(String prefix:Arrays.asList("ABC","General","XYZ")) {
            List<DocumentBlock> blocks=Arrays.asList(line("root",3,.10,.10,prefix+"8.4 Warranty"),line("member",3,.20,.20,"(2) Warranty duties:"),line("a",3,.25,.30,"(a) First duty."),line("b",3,.25,.40,"(b) Second duty."),line("peer",3,.10,.50,prefix+"8.5 Next clause"));
            JsonNode out=build(blocks),root=group(out,prefix.toUpperCase(Locale.ROOT)+"8.4");
            assertTrue(root.path("scopeComplete").asBoolean());assertEquals(4,root.path("bodyBlockIds").size());assertEquals("peer",root.path("endBoundary").path("blockId").asText());
            assertEquals(group(out,prefix.toUpperCase(Locale.ROOT)+"8.4(2)").path("id"),group(out,prefix.toUpperCase(Locale.ROOT)+"8.4(2)(a)").path("parentId"));
        }
    }
    @Test void nativeSameLineNestedMarkersStaySeparateAndShareOnlyOriginalBlockIdentity() {
        List<DocumentBlock> blocks=Arrays.asList(line("root",1,.1,.1,"ABC8.4 Duties"),joined("nested",1,.2,.2,"(5)",.26,"(a)",.31,"A separate duty."),line("b",1,.26,.3,"(b) Another duty."),line("peer",1,.1,.4,"ABC8.5 Next clause"));
        String before=JsonUtils.write(blocks);JsonNode out=build(blocks);assertEquals(group(out,"ABC8.4(5)").path("id"),group(out,"ABC8.4(5)(a)").path("parentId"));assertEquals(group(out,"ABC8.4(5)").path("id"),group(out,"ABC8.4(5)(b)").path("parentId"));assertEquals(before,JsonUtils.write(blocks));
    }
    @Test void continuationPageNeedsBothObservedContentLaneAndNextSiblingMarker() {
        List<DocumentBlock> blocks=Arrays.asList(line("root",6,.10,.10,"ABC8.4 Duties"),line("four",6,.20,.20,"(4) Warranty duties:"),line("d",6,.26,.30,"(d) Keep the condition"),line("tail",6,.28,.35,"as follows on the next page"),line("continuation",7,.28,.10,"until the certificate is issued; and"),line("e",7,.26,.20,"(e) Another duty."),line("peer",7,.10,.40,"ABC8.5 Next clause"));
        JsonNode out=build(blocks),d=group(out,"ABC8.4(4)(d)");assertTrue(d.path("scopeComplete").asBoolean());assertEquals("e",d.path("endBoundary").path("blockId").asText());assertTrue(d.path("bodyBlockIds").toString().contains("continuation"));
    }
    @Test void completePhysicalGridJoinsAllNativeRowsAcrossCellsAndKeepsWholeOriginalSource() {
        List<DocumentBlock> blocks=gridSource();String original=JsonUtils.write(blocks);JsonNode out=build(blocks),d=group(out,"XYZ6.2(4)(d)");
        assertTrue(d.path("scopeComplete").asBoolean(),d.toString());assertEquals(Arrays.asList("d","intro","header","grid-row","tail","continued"),JsonUtils.mapper().convertValue(d.path("bodyBlockIds"),List.class));assertEquals("e",d.path("endBoundary").path("blockId").asText());assertEquals(Collections.singletonList("grid"),JsonUtils.mapper().convertValue(d.path("contextBlockIds"),List.class));
        assertEquals(2,d.path("nativeSyntaxObservations").size());assertFalse(d.path("semanticScopeVerified").asBoolean());assertFalse(d.path("automaticEditEligible").asBoolean());assertEquals(original,JsonUtils.write(blocks));assertFalse(out.path("issues").toString().contains("unknown_column"));
    }
    @Test void physicalCellGeometryCannotJoinAMatchingPrefixInsideALongerWord() {
        List<DocumentBlock> blocks=gridSource();ObjectNode raw=(ObjectNode)blocks.get(blocks.size()-1).getNativeTableCandidate();((ObjectNode)raw.path("candidate").path("logicalTables").get(0).path("origins").get(3)).put("text","Ten yearsX");((ObjectNode)raw.path("candidate").path("tables").get(0).path("cells").get(3)).put("text","Ten yearsX");
        JsonNode d=group(build(blocks),"XYZ6.2(4)(d)");assertFalse(d.path("scopeComplete").asBoolean());assertFalse(d.path("bodyBlockIds").toString().contains("grid-row"));
    }
    @Test void aCrossCellOnlySelectionStillBringsThePreciselyLinkedCompleteMethodGrid() {
        JsonNode graph=crossCellGraph(),part=findPart(graph,"grid-row");ArrayNode selected=JsonUtils.mapper().createArrayNode().add(part.deepCopy());JsonNode context=NormalSourceCandidateGraph.pdfSourceGroupContext(graph,selected);JsonNode method=null;for(JsonNode group:context.path("groups"))if("native_table_method_group".equals(group.path("kind").asText()))method=group;
        assertNotNull(method,context.toString());assertFalse(method.path("bodyBlockIds").toString().contains("grid-row"),"The authored cross-cell fragment deliberately is not an old method seed");assertEquals(4,method.path("methodTable").path("origins").size());assertEquals("a. Material continued material",method.path("methodTable").path("origins").get(2).path("text").asText());assertTrue(context.path("groups").toString().contains("XYZ6.2(4)(d)"));
        assertEquals(JsonUtils.write(context),JsonUtils.write(VettingSourceMetadataWire.decode(VettingSourceMetadataWire.write(context))));
    }
    @Test void aForeignOrMissingMethodLinkCannotExpandSourceContext() {
        for(int mode=0;mode<2;mode++){ObjectNode graph=(ObjectNode)crossCellGraph();JsonNode part=findPart(graph,"grid-row");for(JsonNode group:graph.path("nativePdfSourceGroups").path("groups"))if("XYZ6.2(4)(d)".equals(group.path("reference").asText())){if(mode==0)for(JsonNode observation:group.path("nativeSyntaxObservations"))((ObjectNode)observation).put("methodGroupId","foreign-method-id");else ((ArrayNode)group.path("contextBlockIds")).removeAll();}
            JsonNode context=NormalSourceCandidateGraph.pdfSourceGroupContext(graph,JsonUtils.mapper().createArrayNode().add(part.deepCopy()));assertTrue(context.path("groups").isEmpty());assertFalse(context.path("issues").isEmpty());}
    }
    private JsonNode crossCellGraph(){List<DocumentBlock> blocks=gridSource();ObjectNode raw=(ObjectNode)blocks.get(blocks.size()-1).getNativeTableCandidate();for(JsonNode table:raw.path("candidate").path("logicalTables"))((ObjectNode)table.path("origins").get(2)).put("text","a. Material continued material");((ObjectNode)raw.path("candidate").path("tables").get(0).path("cells").get(2)).put("text","a. Material continued material");blocks.add(blocks.size()-1,line("wrapped-cell",4,.30,.445,"continued material"));
        SourceDocument source=new SourceDocument();source.setId(93L);source.setProjectId("authored-native-pdf");source.setCategory(SourceDocument.CATEGORY_VETTING_PACKAGE);source.setReviewRole("tender");source.setFileKey("SL");source.setFileName("authored.pdf");source.setSourceSha256(SHA);source.setParseStatus("PARSED");source.setPageCount(5);source.setTextContent(String.join("\n",blocks.stream().filter(b->b.getNativeTableCandidate()==null).map(DocumentBlock::getText).toArray(String[]::new)));source.setStructuredContentJson(JsonUtils.write(blocks));ObjectNode coverage=JsonUtils.mapper().createObjectNode();coverage.put("complete",false).put("totalPages",5).put("parsedPages",2).put("ocrPages",0);coverage.putArray("failedPages");source.setParseCoverageJson(JsonUtils.write(coverage));NormalSourceCandidateGraph.capture(source);return JsonUtils.parse(source.getNormalCandidateJson());}
    private JsonNode findPart(JsonNode graph,String block){for(JsonNode unit:graph.path("units"))for(JsonNode part:unit.path("parts"))if(block.equals(part.path("blockId").asText()))return part;throw new AssertionError(block);}
    @Test void missingDuplicateMethodCarrierOrDuplicateNativeSeedCannotProveTableOwnership() {
        for(int mode=0;mode<7;mode++){List<DocumentBlock> blocks=gridSource();DocumentBlock carrier=blocks.get(blocks.size()-1),header=blocks.stream().filter(block->"header".equals(block.getId())).findFirst().orElseThrow();if(mode==0)carrier.setId(null);if(mode==1)blocks.add(carrier);if(mode==2)blocks.add(header);if(mode==3)carrier.setId("");if(mode==4)carrier.setId("   ");if(mode==5)header.setId("");if(mode==6)header.setId("   ");JsonNode d=group(build(blocks),"XYZ6.2(4)(d)");assertFalse(d.path("scopeComplete").asBoolean(),"Only uniquely identified original evidence can prove table membership: "+mode);assertFalse(d.path("bodyBlockIds").toString().contains("grid-row"));}
    }
    @Test void aMixedSmallMarginCanUseAnObservedOrdinaryOrGuidanceBodyColumnWithoutChangingTrueDates() {
        for(boolean guidance:Arrays.asList(false,true)){
            List<DocumentBlock> blocks=new ArrayList<>(Arrays.asList(line("root",1,.10,.10,"XYZ6.2 A complete native title"),line("one",1,.16,.15,"(1) The definition begins here."),line("body",1,.18,.18,"The original definition continues here."),sized("revision-label",1,.10,.20,"Revision 3",6),sized("revision-description",1,.10,.21,"approved under",6),mixedBody("mixed-body",1,.22,"17.04.2031",guidance?"Guidance for the following source item.":"Conditions of the contract continue.",guidance),line("two",1,.16,.30,"(2) The next actual source item."),line("peer",1,.10,.40,"XYZ6.3 The next complete title"),sized("genuine-date",1,.10,.60,"17.04.2031 A genuine smaller numbered provision.",6),line("after-date",1,.10,.70,"18. The next provision."),mixedBody("genuine-mixed-number",1,.80,"19.4 Schedule","A genuine small numbered clause.",false),mixedBody("genuine-mixed-number-two",1,.82,"19.5 Schedule","Another genuine numbered clause.",false),line("genuine-mixed-body",1,.18,.84,"Its ordinary body continues here."),line("final-peer",1,.10,.90,"20. The final provision.")));
            String before=JsonUtils.write(blocks);JsonNode out=build(blocks),one=group(out,"XYZ6.2(1)");assertTrue(one.path("scopeComplete").asBoolean(),one.toString());assertEquals(Arrays.asList("one","body","mixed-body"),JsonUtils.mapper().convertValue(one.path("bodyBlockIds"),List.class));assertEquals("two",one.path("endBoundary").path("blockId").asText());assertEquals("genuine-date",group(out,"17.04.2031").path("sourcePosition").path("blockId").asText());assertEquals("genuine-mixed-number",group(out,"19.4").path("sourcePosition").path("blockId").asText());assertEquals("genuine-mixed-number-two",group(out,"19.5").path("sourcePosition").path("blockId").asText());assertEquals(before,JsonUtils.write(blocks));
        }
    }
    private DocumentBlock sized(String id,int page,double x,double y,String text,double font){DocumentBlock block=line(id,page,x,y,text);int n=0;for(PdfPageEvidence.PdfGlyph glyph:block.getPdfGlyphs()){glyph.setBbox(new double[]{x+n*font*.0005,y,font*.0005,font*.001});glyph.setTextMatrix(new double[]{font,0,0,font,(x+n*font*.0005)*1000,(1-y)*1000});glyph.setFontSize(font);glyph.setFontSizeInPt(font);glyph.setFontName("Authored");n++;}block.setBbox(new double[]{x,y,n*font*.0005,font*.001});return block;}
    private DocumentBlock mixedBody(String id,int page,double y,String margin,String body,boolean bold){DocumentBlock left=sized(id,page,.10,y,margin+" ",6),right=line(id+"-body",page,.18,y+.002,body);if(bold)for(PdfPageEvidence.PdfGlyph glyph:right.getPdfGlyphs())glyph.setFontName("Authored,Bold");left.setText(left.getText()+right.getText());left.setOriginalText(left.getText());left.getPdfGlyphs().addAll(right.getPdfGlyphs());left.setBbox(new double[]{.10,y,.18+body.length()*.005-.10,.012});return left;}
    @Test void trailingSmallWhitespaceCannotCloseTheObservedInkGapOrPromoteASidebarMarker() {
        List<DocumentBlock> blocks=new ArrayList<>(Arrays.asList(line("root",1,.10,.10,"XYZ6.2 Native source heading"),line("one",1,.148,.15,"(1) The source clause begins."),line("body",1,.168,.18,"The original source body continues."),sized("margin-label",1,.10,.20,"reference label",6),paddedMargin(),sized("margin-number",1,.10,.24,"09.11 .2044",6),line("two",1,.148,.30,"(2) The actual next source item."),line("peer",1,.10,.40,"XYZ6.3 The next actual heading")));
        String original=JsonUtils.write(blocks);JsonNode out=build(blocks),one=group(out,"XYZ6.2(1)");assertTrue(one.path("scopeComplete").asBoolean(),one.toString());assertEquals(Arrays.asList("one","body","padded-margin"),JsonUtils.mapper().convertValue(one.path("bodyBlockIds"),List.class));assertEquals("two",one.path("endBoundary").path("blockId").asText());for(JsonNode item:out.path("groups"))assertFalse("source_clause".equals(item.path("kind").asText())&&"margin-number".equals(item.path("sourcePosition").path("blockId").asText()),"A source marker cannot originate in the proven marginal glyph run, even if spaces split its number.");assertEquals(original,JsonUtils.write(blocks));
    }
    private DocumentBlock paddedMargin(){DocumentBlock left=sized("padded-margin",1,.10,.22,"annotation  ",6),right=line("padded-main",1,.168,.222,"The native paragraph continues here.");List<PdfPageEvidence.PdfGlyph> small=left.getPdfGlyphs();for(int i=0;i<2;i++){PdfPageEvidence.PdfGlyph glyph=small.get(small.size()-2+i);double x=i==0?.150:.157;glyph.setBbox(new double[]{x,.22,.003,.006});glyph.setTextMatrix(new double[]{6,0,0,6,x*1000,780});}left.setText(left.getText()+right.getText());left.setOriginalText(left.getText());left.getPdfGlyphs().addAll(right.getPdfGlyphs());left.setBbox(new double[]{.10,.22,.168+right.getText().length()*.005-.10,.012});return left;}
    private List<DocumentBlock> gridSource(){List<DocumentBlock> blocks=new ArrayList<>(Arrays.asList(line("root",4,.10,.10,"XYZ6.2 Duties"),line("four",4,.20,.20,"(4) Warranty:"),line("d",4,.26,.30,"(d) Retain the conditions"),line("intro",4,.28,.33,"for the following periods:"),joined("header",4,.30,.37,"Item",.50,"Period",.55,""),joined("grid-row",4,.30,.43,"a. Material",.50,"Ten years",.56,""),line("tail",4,.28,.50,"and the period shall commence"),line("continued",5,.28,.10,"from the certificate date; and"),line("e",5,.26,.20,"(e) Another duty.")));blocks.add(grid());return blocks;}
    private DocumentBlock grid(){
        DocumentBlock b=new DocumentBlock();b.setId("grid");b.setPageNo(4);b.setKind("native_table_candidate");b.setSource("native_table_candidate");ObjectNode raw=JsonUtils.mapper().createObjectNode();raw.put("provider","authored").put("method","authored_grid").put("status","candidate_observed").put("physicalPageNo",4).put("sourceSha256",SHA).put("nativeGlyphNamespace","pdfplumber/page/4");ObjectNode frame=JsonUtils.mapper().createObjectNode();frame.put("coordinateSpace","PDF_points_crop_top_left").put("pageWidth",1000).put("pageHeight",1000).put("rotation",0).put("pdfplumberPageWidth",1000).put("pdfplumberPageHeight",1000).put("originalPdfRotate",0).put("pdfUserUnit",1);for(String key:Arrays.asList("pdfplumberMediaBox","pdfplumberCropBox","pdfplumberPageBbox","originalPdfMediaBox","originalPdfCropBox"))frame.set(key,JsonUtils.mapper().valueToTree(new double[]{0,0,1000,1000}));ObjectNode transform=frame.putObject("sourceCoordinateTransform");transform.put("from","pdfplumber_rotated_media_top_left").put("to","PDF_points_crop_top_left").put("inputCroppingPerformed",false);transform.putArray("translation").add(0).add(0);raw.set("frame",frame);
        for(String key:Arrays.asList("rawRef","bundleRef","sourceObservationRef"))raw.putObject(key).put("schema","consense.artifact-descriptor.v1").put("storage","content_addressed_disk").put("sha256",SHA).put("byteCount",1).put("identityScope","authored saved observation");
        ObjectNode candidate=raw.putObject("candidate");candidate.put("provider","authored").put("method","authored_grid").put("physicalPageNo",4).put("sourceSha256",SHA).put("nativeGlyphNamespace","pdfplumber/page/4");candidate.set("frame",frame.deepCopy());ObjectNode table=candidate.putArray("logicalTables").addObject();table.put("tableId","logical-grid").put("providerTableId","physical-grid").put("textTransform","none_original_physical_cell_literals").put("rowCount",2).put("colCount",2);table.set("bbox",JsonUtils.mapper().valueToTree(new double[]{280,360,700,460}));ArrayNode origins=table.putArray("origins");String[] texts={"Item","Period","a. Material","Ten years"};
        for(int i=0;i<4;i++){int row=i/2,col=i%2;ObjectNode cell=origins.addObject();cell.put("row",row).put("col",col).put("rowSpan",1).put("colSpan",1).put("spanKnown",true).put("text",texts[i]);cell.set("bbox",JsonUtils.mapper().valueToTree(new double[]{col==0?280:480,row==0?360:410,col==0?480:700,row==0?400:460}));cell.putArray("physicalCellIds").add("physical-cell-"+i);cell.putArray("glyphIds").add(i);}
        ObjectNode physical=candidate.putArray("tables").addObject();physical.put("tableId","physical-grid");ArrayNode cells=physical.putArray("cells");for(int i=0;i<4;i++){ObjectNode cell=((ObjectNode)origins.get(i)).deepCopy();cell.remove("physicalCellIds");cell.put("physicalCellId","physical-cell-"+i);cells.add(cell);}physical.putArray("issues");ObjectNode coverage=physical.putObject("coverage");for(String key:Arrays.asList("required","present")){ArrayNode values=coverage.putArray(key);for(int i=0;i<4;i++)values.add(i);}coverage.putArray("missing");coverage.putArray("duplicate");ObjectNode group=candidate.putObject("observationGroups").putArray("groups").addObject();group.put("tableId","logical-grid");group.putArray("members");group.putArray("relations");b.setNativeTableCandidate(raw);return b;
    }
    private JsonNode build(List<DocumentBlock> blocks){ObjectNode coverage=JsonUtils.mapper().createObjectNode();coverage.put("complete",false);return NormalPdfSourceGroups.build(blocks,SHA,coverage);}
    private JsonNode group(JsonNode out,String key){List<JsonNode> found=new ArrayList<>();for(JsonNode group:out.path("groups"))if("source_clause".equals(group.path("kind").asText())&&key.equals(group.path("reference").asText()))found.add(group);assertEquals(1,found.size(),key);return found.get(0);}
    private DocumentBlock joined(String id,int page,double x,double y,String a,double x2,String b,double x3,String c){DocumentBlock first=line(id,page,x,y,a+" "),second=line(id+"-b",page,x2,y,b+" "),third=line(id+"-c",page,x3,y,c);first.setText(a+" "+b+" "+c);first.setOriginalText(first.getText());first.getPdfGlyphs().addAll(second.getPdfGlyphs());first.getPdfGlyphs().addAll(third.getPdfGlyphs());first.setBbox(new double[]{x,y,x3+c.length()*.005-x,.01});return first;}
    private DocumentBlock line(String id,int page,double x,double y,String text){DocumentBlock block=new DocumentBlock();block.setId(id);block.setKind("pdf_line");block.setSource("native");block.setPageNo(page);block.setText(text);block.setOriginalText(text);block.setBbox(new double[]{x,y,text.codePointCount(0,text.length())*.005,.01});ObjectNode context=JsonUtils.mapper().createObjectNode();context.put("sourceSha256",SHA);block.setReadingContext(context);int offset=0,n=0;while(offset<text.length()){int point=text.codePointAt(offset);String value=new String(Character.toChars(point));PdfPageEvidence.PdfGlyph glyph=new PdfPageEvidence.PdfGlyph();glyph.setId("pdf-page/"+page+"/glyph/"+id+"/"+n);glyph.setUnicode(value);glyph.setCoordinateSpace(FRAME);glyph.setEligibleForNativeText(true);glyph.setBbox(new double[]{x+n*.005,y,.005,.01});glyph.setTextMatrix(new double[]{10,0,0,10,(x+n*.005)*1000,(1-y)*1000});glyph.setFontSize(10);glyph.setFontSizeInPt(10);glyph.setPdfboxPosition(new double[]{0,0,0,0,0,0,0,0,1000,1000});glyph.setFontName(text.matches("^[A-Za-z]+[0-9].*")?"Authored,Bold":"Authored");block.getPdfGlyphs().add(glyph);offset+=value.length();n++;}return block;}
}
